fixes.new_str:
useEffect(() => {
  let animId: number;
  let running = true;
  const loop = () => {
    if (!running) return;
    animate();
    animId = requestAnimationFrame(loop);
  };
  animId = requestAnimationFrame(loop);
  return () => {
    running = false;
    cancelAnimationFrame(animId);
  };
}, []);
